-- Instances -----------------------------------------------------------------

---Anything in the game tree. Every class below is a kind of Instance.
---@class Instance
---@field Name string The Instance's name. Children can be found by name: `workspace.Block`.
---@field ClassName string The Instance's class, such as `"Part"`. Read-only.
---@field Parent Instance? The Instance this one is inside, or nil. Setting it moves the Instance.
---@field Changed Signal Fires when a property (or `Name` or `Parent`) gets a different value, whether a script, physics or the editor changed it. The handler gets the property's name: `function(property) ... end`.
---@field ChildAdded Signal Fires when an Instance is put inside this one. The handler gets the child.
---@field ChildRemoved Signal Fires when an Instance is taken out of this one. The handler gets the child.
---@field [string] Workspace|Players|ReplicatedStorage|ServerScriptService|StarterPlayer|StarterPlayerScripts|Part|MeshPart|Script|LocalScript|ModuleScript|RemoteEvent|Player|Model|Folder A child, found by its name.
local InstanceClass = {}

---The first child with this name, or nil. With `recursive`, searches every descendant.
---@param name string
---@param recursive? boolean
---@return Instance?
function InstanceClass:FindFirstChild(name, recursive) end

---An event that fires when this one property (or `Name` or `Parent`) gets a different value. The handler gets nothing: read the property to see its new value.
---@param property string
---@return Signal
function InstanceClass:GetPropertyChangedSignal(property) end

---An event, such as `part.Touched`. Connect a function to run it every time the event fires.
---@class Signal
local SignalClass = {}

---Runs `callback` every time the event fires, each time as its own task (so it may `task.wait`). Returns a Connection for stopping it.
---@param callback function
---@return Connection
function SignalClass:Connect(callback) end

---A function connected to an event, returned by `Connect`.
---@class Connection
---@field Connected boolean True until `Disconnect` is called (or the Instance is destroyed).
local ConnectionClass = {}

---Stops the function from running when the event fires again. Calling it twice is harmless.
---@return nil
function ConnectionClass:Disconnect() end

---The root of the game, called `game` in scripts.
---@class DataModel: Instance
---@field Workspace Workspace The service that holds the 3D world. Parts inside it are drawn.
---@field Players Players The service with a Player for everyone in the game.
---@field ReplicatedStorage ReplicatedStorage The service for things Scripts and LocalScripts share, such as RemoteEvents and ModuleScripts.
---@field ServerScriptService ServerScriptService The service that holds server scripts (`scripts/*.server.lua`).
---@field StarterPlayer StarterPlayer The service with what each player starts with, such as StarterPlayerScripts.
---@field UserInputService UserInputService The player's keyboard (same as `game:GetService("UserInputService")`). LocalScripts only.
---@field RunService RunService The game's frame loop, with `Heartbeat` (same as `game:GetService("RunService")`).
local DataModelClass = {}

---The service with this class name, such as `"Players"`, `"RunService"` or `"UserInputService"`.
---@param className string
---@return Instance
function DataModelClass:GetService(className) end


---The service that holds the 3D world. Parts inside it are drawn.
---@class Workspace: Instance
---@field CurrentCamera Camera The camera the player sees through. LocalScripts only.

---The service with a Player for everyone in the game.
---@class Players: Instance
---@field LocalPlayer Player The player on this device. LocalScripts only.

---The service for things Scripts and LocalScripts share, such as RemoteEvents and ModuleScripts.
---@class ReplicatedStorage: Instance

---The service that holds server scripts (`scripts/*.server.lua`).
---@class ServerScriptService: Instance

---The service with what each player starts with, such as StarterPlayerScripts.
---@class StarterPlayer: Instance

---Holds the LocalScripts (`scripts/*.client.lua`), which run on the player's side.
---@class StarterPlayerScripts: Instance

---A solid shape in the world.
---@class Part: Instance
---@field Anchored boolean If true, the part stays where it is. If false, it falls and collides with other parts.
---@field Shape EnumItem.PartType|"Block"|"Ball"|"Cylinder"|"Wedge" Block, Ball, Cylinder (along X) or Wedge.
---@field Position Vector3 Where the part's center is, in studs. Setting it on an unanchored part teleports it and stops it moving.
---@field Orientation Vector3 Rotation in degrees around X, Y and Z, applied Z first, then X, then Y.
---@field Size Vector3 The part's size in studs along X, Y and Z.
---@field Color Color3 The part's color.
---@field Material EnumItem.Material|"Plastic"|"Metal"|"Glass"|"Neon" Plastic, Metal, Glass (see-through) or Neon (glows). Setting it resets Metalness and Roughness.
---@field Metalness number From 0 (not metal) to 1 (metal).
---@field Roughness number From 0 (mirror-smooth) to 1 (matte).
---@field Touched Signal Fires when another part starts touching this one, once per new contact (not every frame while they touch). The handler gets the other part: `part.Touched:Connect(function(otherPart) ... end)`.

---A solid 3D model imported from a glTF file, drawn with the file's own materials. It collides as the model's convex hull.
---@class MeshPart: Instance
---@field Anchored boolean If true, the part stays where it is. If false, it falls and collides with other parts.
---@field MeshId string The model's glTF file, inside the project folder, such as "assets/models/chair.glb". The editor's Import Model sets it.
---@field Position Vector3 Where the center of the model's box is, in studs. Setting it on an unanchored part teleports it and stops it moving.
---@field Orientation Vector3 Rotation in degrees around X, Y and Z, applied Z first, then X, then Y.
---@field Size Vector3 The size of the model's box in studs along X, Y and Z. The model stretches to fill it.
---@field Touched Signal Fires when another part starts touching this one, once per new contact (not every frame while they touch). The handler gets the other part: `part.Touched:Connect(function(otherPart) ... end)`.

---Lua code that runs on the server, from a `.server.lua` file.
---@class Script: Instance

---Lua code that runs on the player's side (input, camera), from a `.client.lua` file.
---@class LocalScript: Instance

---Lua code that scripts load with `require`, from a `.module.lua` file. It runs once per side and returns one value.
---@class ModuleScript: Instance

---Carries messages between Scripts and LocalScripts. Keep it in ReplicatedStorage.
---@class RemoteEvent: Instance
---@field OnServerEvent Signal Fires when a LocalScript calls `FireServer`. The handler gets the Player who sent it, then the arguments: `function(player, ...) ... end`. Scripts only.
---@field OnClientEvent Signal Fires when a Script calls `FireClient` or `FireAllClients`. The handler gets the arguments. LocalScripts only.
local RemoteEventClass = {}

---Sends the arguments to the server, where `OnServerEvent` fires with this player first. LocalScripts only.
---@param ... any
---@return nil
function RemoteEventClass:FireServer(...) end

---Sends the arguments to one player, where `OnClientEvent` fires. Scripts only.
---@param player Player
---@param ... any
---@return nil
function RemoteEventClass:FireClient(player, ...) end

---Sends the arguments to every player, where `OnClientEvent` fires. Scripts only.
---@param ... any
---@return nil
function RemoteEventClass:FireAllClients(...) end


---Someone playing the game, in Players. Made when they join.
---@class Player: Instance

---Groups the parts of one thing, such as a car or a house.
---@class Model: Instance

---Groups Instances to keep the tree tidy. Has no effect on the game.
---@class Folder: Instance

-- Globals -------------------------------------------------------------------

---The root of the game. Every service is inside it.
---@type DataModel
game = nil

---The service that holds the 3D world (same as `game.Workspace`).
---@type Workspace
workspace = nil

---The Script, LocalScript or ModuleScript that is running this code.
---@type Script|LocalScript|ModuleScript
script = nil

---Every enum, such as `Enum.Material`, `Enum.PartType` and `Enum.KeyCode`.
---@type EnumLibrary
Enum = nil

---Runs a ModuleScript (a `.module.lua` file, such as `require(game.ReplicatedStorage.Utils)`) the first time, and returns what it returned. Later calls on the same side return the same value.
---@param module Instance
---@return any
function require(module) end

---Creates Instances.
---@class InstanceLibrary
Instance = {}

---Creates an Instance of this class with default properties and no parent. Set `Parent` to put it in the world.
---@param className string
---@return Instance
---@overload fun(className: "Part"): Part
---@overload fun(className: "MeshPart"): MeshPart
---@overload fun(className: "Script"): Script
---@overload fun(className: "LocalScript"): LocalScript
---@overload fun(className: "ModuleScript"): ModuleScript
---@overload fun(className: "RemoteEvent"): RemoteEvent
---@overload fun(className: "Model"): Model
---@overload fun(className: "Folder"): Folder
function Instance.new(className) end

---Creates Vector3 values.
---@class Vector3Library
Vector3 = {}

---A new Vector3. Left-out components are 0.
---@param x? number
---@param y? number
---@param z? number
---@return Vector3
function Vector3.new(x, y, z) end

---Creates Color3 values.
---@class Color3Library
Color3 = {}

---A color from channels between 0 and 1. Left-out channels are 0.
---@param r? number
---@param g? number
---@param b? number
---@return Color3
function Color3.new(r, g, b) end

---A color from channels between 0 and 255, as in most paint programs.
---@param r? number
---@param g? number
---@param b? number
---@return Color3
function Color3.fromRGB(r, g, b) end

---Pauses scripts and runs functions later, without stopping the game.
---@class taskLibrary
task = {}

---Pauses this code for `seconds` (left out: until the next frame), while the game and other scripts keep running. Returns the seconds that really passed.
---@param seconds? number
---@return number
function task.wait(seconds) end

---Runs `callback` right away with the given arguments, until it finishes or waits, then carries on here. An error inside it is reported without stopping this code.
---@param callback function
---@param ... any
---@return thread
function task.spawn(callback, ...) end

---Runs `callback` with the given arguments after `seconds`, without pausing this code.
---@param seconds number
---@param callback function
---@param ... any
---@return thread
function task.delay(seconds, callback, ...) end
